def _seed_system_codes() -> None:
    codes = sa.table(
        "codes",
        sa.column("id", sa.Uuid()),
        sa.column("key", sa.String()),
        sa.column("name", sa.String()),
        sa.column("is_system", sa.Boolean()),
    )
    code_values = sa.table(
        "code_values",
        sa.column("id", sa.Uuid()),
        sa.column("code_id", sa.Uuid()),
        sa.column("key", sa.String()),
        sa.column("label", sa.String()),
        sa.column("sort_order", sa.Integer()),
        sa.column("is_active", sa.Boolean()),
    )
    code_rows = []
    value_rows = []
    for code_key, code_name, values in SYSTEM_CODES:
        code_id = uuid.uuid4()
        code_rows.append(
            {"id": code_id, "key": code_key, "name": code_name, "is_system": True}
        )
        for position, (value_key, label, is_active) in enumerate(values, start=1):
            value_rows.append(
                {
                    "id": uuid.uuid4(),
                    "code_id": code_id,
                    "key": value_key,
                    "label": label,
                    "sort_order": position,
                    "is_active": is_active,
                }
            )
    op.bulk_insert(codes, code_rows)
    op.bulk_insert(code_values, value_rows)


